import java.nio.*;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
import org.lwjgl.glfw.GLFW;
import org.lwjgl.opengl.*;
import com.iridium126.createmanaindustry.client.particles.engine.hardware.HardwareNative;

/** COPY ownership/overlap probe with independent raster work, not a Minecraft FPS test. */
public final class R7CopyConcurrencyGpu extends ModelPopulationGpuValidation {
    static int shader(int type,String text){int s=GL20.glCreateShader(type);GL20.glShaderSource(s,text);GL20.glCompileShader(s);check(GL20.glGetShaderi(s,GL20.GL_COMPILE_STATUS)!=0,GL20.glGetShaderInfoLog(s));return s;}
    static int program(){int v=shader(GL20.GL_VERTEX_SHADER,"#version 450 core\nvoid main(){vec2 p=vec2((gl_VertexID<<1)&2,gl_VertexID&2);gl_Position=vec4(p*2.-1.,0,1);}"),f=shader(GL20.GL_FRAGMENT_SHADER,"#version 450 core\nuniform uint seed;layout(location=0)out vec4 color;void main(){uint v=uint(gl_FragCoord.x)+uint(gl_FragCoord.y)*8191u+seed;for(int i=0;i<64;i++){v=v*1664525u+1013904223u;v^=v>>13u;}color=vec4(float(v&255u),float((v>>8u)&255u),float((v>>16u)&255u),255.)/255.;}");int p=GL20.glCreateProgram();GL20.glAttachShader(p,v);GL20.glAttachShader(p,f);GL20.glLinkProgram(p);check(GL20.glGetProgrami(p,GL20.GL_LINK_STATUS)!=0,GL20.glGetProgramInfoLog(p));GL20.glDeleteShader(v);GL20.glDeleteShader(f);return p;}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(System.getProperty("cmi.benchmark.output")),input=Path.of(System.getProperty("cmi.r7.copyInput"));Files.createDirectories(out);check(!Files.exists(out.resolve("samples.csv")),"fresh run");byte[] payload=Files.readAllBytes(input);check(payload.length>0&&payload.length<=64*1024*1024,"bounded real state input");
        check(GLFW.glfwInit(),"GLFW");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MAJOR,4);GLFW.glfwWindowHint(GLFW.GLFW_CONTEXT_VERSION_MINOR,6);long window=GLFW.glfwCreateWindow(32,32,"R7 COPY and raster concurrency",0,0);check(window!=0,"GL context");GLFW.glfwMakeContextCurrent(window);GL.createCapabilities();HardwareNative.load(Path.of(".gradle/hardware-offload/build"));
        long nativeHandle=HardwareNative.createCopy(payload.length,3);int p=program(),vao=GL30.glGenVertexArrays(),fbo=GL30.glGenFramebuffers(),texture=GL11.glGenTextures(),timer=GL15.glGenQueries();int[][] buffers=new int[3][];
        var metadata=new LinkedHashMap<String,Object>();metadata.put("passed",false);metadata.put("scope","whole frozen particle-state COPY plus independent synthetic raster work; no authoritative simulation continuation, actual shaderpack terrain or client FPS");metadata.put("bridge",JsonParser.parseString(HardwareNative.copyInfo(nativeHandle)));metadata.put("input",input.toAbsolutePath().toString());metadata.put("input_sha256",HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(payload)));metadata.put("driver",GL11.glGetString(GL11.GL_VERSION));metadata.put("process_id",ProcessHandle.current().pid());metadata.put("size",List.of(2560,1506));
        try(var raw=Files.newBufferedWriter(out.resolve("samples.csv"))){
            GL11.glBindTexture(GL11.GL_TEXTURE_2D,texture);GL42.glTexStorage2D(GL11.GL_TEXTURE_2D,1,GL11.GL_RGBA8,2560,1506);GL30.glBindFramebuffer(GL30.GL_FRAMEBUFFER,fbo);GL30.glFramebufferTexture2D(GL30.GL_FRAMEBUFFER,GL30.GL_COLOR_ATTACHMENT0,GL11.GL_TEXTURE_2D,texture,0);check(GL30.glCheckFramebufferStatus(GL30.GL_FRAMEBUFFER)==GL30.GL_FRAMEBUFFER_COMPLETE,"FBO");GL11.glViewport(0,0,2560,1506);GL11.glDisable(GL11.GL_DEPTH_TEST);GL11.glDisable(GL11.GL_BLEND);GL11.glDisable(GL11.GL_CULL_FACE);GL30.glBindVertexArray(vao);GL20.glUseProgram(p);
            for(int slot=0;slot<3;slot++){buffers[slot]=HardwareNative.copyBuffers(nativeHandle,slot);put(buffers[slot][0],org.lwjgl.BufferUtils.createByteBuffer(payload.length).put(payload).flip());}
            raw.write("comparison,pair,side,mode,slot,gl_interval_ms,cpu_submit_ms,copy_queue_ms\n");int iteration=0;
            for(int[] comparison:new int[][]{{0,0},{1,1},{2,2},{0,1},{0,2},{1,2}}){String label=(comparison[0]==comparison[1]?"AA_":"AB_")+comparison[0]+"_"+comparison[1];for(int pair=-12;pair<64;pair++)for(int turn=0;turn<2;turn++){
                int side=(pair+turn)&1,mode=comparison[side],slot=iteration++%3;int[] ids=buffers[slot];GL15.glBeginQuery(GL33.GL_TIME_ELAPSED,timer);long started=System.nanoTime();
                if(mode==0){GL42.glMemoryBarrier(GL42.GL_BUFFER_UPDATE_BARRIER_BIT);GL15.glBindBuffer(GL31.GL_COPY_READ_BUFFER,ids[0]);GL15.glBindBuffer(GL31.GL_COPY_WRITE_BUFFER,ids[1]);GL31.glCopyBufferSubData(GL31.GL_COPY_READ_BUFFER,GL31.GL_COPY_WRITE_BUFFER,0,0,payload.length);}else check(mode==1?HardwareNative.submitCopy(nativeHandle,slot,payload.length):HardwareNative.beginCopy(nativeHandle,slot,payload.length),"retired COPY slot");
                GL30.glUniform1ui(GL20.glGetUniformLocation(p,"seed"),pair+12);for(int repeat=0;repeat<4;repeat++)GL11.glDrawArrays(GL11.GL_TRIANGLES,0,3);
                if(mode==2)HardwareNative.awaitCopy(nativeHandle,slot);double cpu=(System.nanoTime()-started)/1e6;GL15.glEndQuery(GL33.GL_TIME_ELAPSED);double elapsed=GL33.glGetQueryObjectui64(timer,GL15.GL_QUERY_RESULT)/1e6;
                if(pair>=0)raw.write(label+","+pair+","+side+","+mode+","+slot+","+elapsed+","+cpu+","+(mode==0?-1:HardwareNative.copyMillis(nativeHandle,slot))+"\n");
                if(pair==0||pair==63){check(Arrays.equals(payload,R6CaptureReplayGpu.Capture.array(R7HardwareGpu.readShared(ids[1],payload.length))),"exact GL COPY result");if(mode!=0)check(Arrays.equals(payload,HardwareNative.readCopyCuda(nativeHandle,slot,payload.length)),"exact CUDA COPY result");var pixel=bytes(4);GL11.glReadPixels(0,0,1,1,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,pixel);int hash=pair+12;for(int i=0;i<64;i++){hash=hash*1664525+1013904223;hash^=hash>>>13;}check((pixel.get(0)&255)==(hash&255)&&(pixel.get(1)&255)==((hash>>>8)&255)&&(pixel.get(2)&255)==((hash>>>16)&255),"unchanged raster output");}
            }raw.flush();}check(GL11.glGetError()==0,"GL state");metadata.put("passed",true);
        }finally{metadata.put("checks",checks);Files.writeString(out.resolve("metadata.json"),new GsonBuilder().setPrettyPrinting().create().toJson(metadata)+"\n");GL15.glDeleteQueries(timer);GL11.glDeleteTextures(texture);GL30.glDeleteFramebuffers(fbo);GL30.glDeleteVertexArrays(vao);GL20.glDeleteProgram(p);HardwareNative.closeCopy(nativeHandle);GLFW.glfwDestroyWindow(window);GLFW.glfwTerminate();}
    }
}
